{
  "actions": [
    {
      "action": "Separate visible-page selection from all matching records",
      "mechanism": "Explicit scope choices distinguish the 25 visible records from the 600 matching records before confirmation.",
      "implementation": "Provide separate labeled controls. Show a persistent summary: count, filter description, target status, and whether selection spans pages.",
      "check": "Using keyboard only, select each scope; verify the confirmation and submitted ID count agree, including after page navigation.",
      "risk": "A generic “Select all” label would reintroduce ambiguity."
    },
    {
      "action": "Freeze the exact confirmed record set",
      "mechanism": "An immutable ID manifest prevents changing filters or new matches from silently expanding the confirmed operation.",
      "implementation": "Resolve matching IDs before confirmation; bind confirmation to that manifest. Execute explicit manifest IDs, never rerun the filter for membership.",
      "check": "Add matching records and change filters after confirmation; assert every dispatched ID belongs to the original confirmed manifest.",
      "risk": "Resolving the manifest may delay confirmation; expose progress."
    },
    {
      "action": "Reject records changed since the confirmed snapshot",
      "mechanism": "Atomic version preconditions prevent overwriting intervening edits, while unchanged records can still succeed independently.",
      "implementation": "Capture record versions with the manifest. Add server-side conditional updates that atomically compare each version and return conflicts as per-record outcomes.",
      "check": "Change one record between confirmation and execution; verify that record reports conflict and retains its newer state while others proceed.",
      "risk": "Client-side checks alone leave a race window."
    },
    {
      "action": "Preserve a resumable per-record operation receipt",
      "mechanism": "Durable outcomes distinguish completed changes, failures, and unresolved requests even when navigation or network interruption hides progress.",
      "implementation": "Persist operation ID, confirmed manifest, and per-record outcomes. Restore a receipt showing succeeded, failed, conflicted, pending, and unknown counts.",
      "check": "Interrupt a batch and reload; verify restored counts reconcile with the manifest and unresolved records are not labeled successful.",
      "risk": "Lost responses require server reconciliation, not guessed outcomes."
    },
    {
      "action": "Retry failures without replaying successful changes",
      "mechanism": "Outcome-based retry sets and server-side deduplication isolate recovery from work that has already completed successfully.",
      "implementation": "Offer “Retry failed records.” Enforce original-manifest membership, exclude successes, reconcile unknown outcomes, and deduplicate writes by operation and record.",
      "check": "Mix successes, failures, and lost responses; retry twice and verify successes receive no additional writes and no outside IDs appear.",
      "risk": "Conflicts require refreshed information and renewed confirmation before overwrite."
    },
    {
      "action": "Make reversal eligibility explicit for each record",
      "mechanism": "A reversal receipt explains whether the deadline elapsed or a subsequent change prevents restoring the earlier status.",
      "implementation": "Store prior status, resulting version, and server deadline. Atomically reverse only eligible confirmed IDs; show textual per-record reasons when unavailable.",
      "check": "Test unchanged, subsequently edited, expired, and edited-back records; only eligible records reverse, and every rejection displays its actual reason.",
      "risk": "Displayed eligibility can expire before activation; revalidate server-side."
    },
    {
      "action": "Make the whole workflow keyboard and screen-reader operable",
      "mechanism": "Semantic controls, predictable focus, and concise announcements expose scope and outcomes without depending on pointer interaction or color.",
      "implementation": "Use labeled native controls, a navigable scope summary, throttled live progress, and keyboard-accessible outcome filters. Preserve focus when rows update.",
      "check": "Complete selection, confirmation, failure recovery, and reversal using only keyboard and screen reader; verify counts and rejection reasons are discoverable.",
      "risk": "Announcing every record outcome would overwhelm the workflow."
    }
  ],
  "abstention_reason": ""
}
